) AS v(machine_class, location, machine_name, machine_description, currency_code, country_code, source_type, process_group, operators, setup_time_hr, landed_machine_cost, direct_overhead_rate, indirect_overhead_rate, benchmark_direct_overhead_rate_usd_hr, benchmark_indirect_overhead_rate_usd_hr, total_machine_hour_rate, mhr_usd_per_hour, usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total, work_center_labor_rate_factor, labor_time_standard, wage_grade, machine_price_usd, machine_length_mm, machine_width_mm, footprint_allowance_factor, machine_power_kw, machine_life_yr, installation_factor_pct, machine_uptime_pct, annual_maintenance_factor_pct, salvage_value_factor_pct, supplies_cost_per_year, avg_utilization, good_part_yield, manufacturer_country, max_x_mm, max_y_mm, max_z_mm, max_workpiece_weight_kg, capability_source, specs, benchmark_source_key)
WHERE NOT EXISTS (
  SELECT 1 FROM mhr_records m
  WHERE m.machine_class = v.machine_class
    AND m.location = v.location
    AND lower(trim(m.machine_name)) = lower(trim(v.machine_name))
);

DO $pcba_india$
DECLARE
  cols text; sel text; r record; src_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '$5'
        WHEN 'country_code'                            THEN '$6'
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN '$7'
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'src.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  -- (location, country, machine class, machine name, labour, direct overhead, indirect overhead, source key), USD/hr
  FOR r IN SELECT * FROM (VALUES
    ($str$India$str$, $str$IN$str$, $str$pcba_aoi$str$, $str$Koh Young Zenith F 3D AOI$str$, 1.73, 5.58, 0.89, $str$Assembly AOI:Koh Young Zenith F 3D AOI:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_aoi$str$, $str$Omron VT-S530 AOI$str$, 1.73, 0.99, 0.89, $str$Assembly AOI:Omron VT-S530 AOI:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_aoi$str$, $str$Sinic-Tek LT-M330D online AOI$str$, 1.73, 0.61, 0.89, $str$Assembly AOI:Sinic-Tek LT-M330D online AOI:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_depanel_router$str$, $str$GAM320A router (Kiritsu India)$str$, 1.73, 1.83, 0.86, $str$Depanel Router:GAM320A router (Kiritsu India):India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_depanel_router$str$, $str$Genitec GAM320 router (Hibex India)$str$, 1.73, 1.12, 0.86, $str$Depanel Router:Genitec GAM320 router (Hibex India):India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_depanel_router$str$, $str$I.C.T-5700N offline PCBA router$str$, 1.73, 1.3, 0.91, $str$Depanel Router:I.C.T-5700N offline PCBA router:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_depanel_router$str$, $str$Indus Robotics PCB depaneling router$str$, 1.73, 0.63, 0.9, $str$Depanel Router:Indus Robotics PCB depaneling router:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_flying_probe$str$, $str$I.C.T A40 flying probe$str$, 2.3, 2.81, 0.94, $str$Assembly Flying Probe:I.C.T A40 flying probe:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_in_circuit_test$str$, $str$I.C.T-Q588A online ICT$str$, 1.73, 1.57, 0.88, $str$In-Circuit Test:I.C.T-Q588A online ICT:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_pick_and_place$str$, $str$Yamaha YSM20R$str$, 1.73, 3.25, 0.94, $str$Pick and Place:Yamaha YSM20R:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_reflow$str$, $str$Heller 1809 MK5$str$, 1.73, 2.67, 1.07, $str$Reflow Solder:Heller 1809 MK5:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_reflow$str$, $str$JT JTR-800-N$str$, 1.73, 3.18, 0.86, $str$Reflow Solder:JT JTR-800-N:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_reflow$str$, $str$Kait KTE-1000$str$, 1.73, 2.24, 1.11, $str$Reflow Solder:Kait KTE-1000:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_selective_solder$str$, $str$Sundarc AS-350C selective wave$str$, 1.73, 2.18, 0.86, $str$Selective Solder:Sundarc AS-350C selective wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_selective_solder$str$, $str$Sundarc FS-250C desktop selective wave$str$, 1.73, 1.56, 0.89, $str$Selective Solder:Sundarc FS-250C desktop selective wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_selective_solder$str$, $str$Sundarc XS-350C dual-pot selective wave$str$, 1.73, 6.15, 0.99, $str$Selective Solder:Sundarc XS-350C dual-pot selective wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_solder_paste_inspection$str$, $str$Koh Young KY8030-2$str$, 1.73, 3.15, 0.86, $str$Solder Paste Inspection:Koh Young KY8030-2:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_solder_paste_inspection$str$, $str$Sinic-Tek B3 in-line 3D SPI$str$, 1.73, 0.68, 0.89, $str$Solder Paste Inspection:Sinic-Tek B3 in-line 3D SPI:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_stencil_printer$str$, $str$GKG G5$str$, 2.3, 1.71, 0.91, $str$Stencil Print:GKG G5:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_stencil_printer$str$, $str$GKG GT++$str$, 2.3, 2.46, 0.86, $str$Stencil Print:GKG GT++:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_wave_solder$str$, $str$Chipbest FMW-350 lead-free dual wave$str$, 1.73, 3.79, 1.07, $str$Wave Solder:Chipbest FMW-350 lead-free dual wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_wave_solder$str$, $str$I.C.T W2 lead-free wave$str$, 1.73, 0.82, 0.86, $str$Wave Solder:I.C.T W2 lead-free wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_wave_solder$str$, $str$Jaguar N350 lead-free wave$str$, 1.73, 3.82, 1.03, $str$Wave Solder:Jaguar N350 lead-free wave:India$str$),
    ($str$India$str$, $str$IN$str$, $str$pcba_wave_solder$str$, $str$SFG SH-350 lead-free wave$str$, 1.73, 1.21, 1.07, $str$Wave Solder:SFG SH-350 lead-free wave:India$str$)
  ) AS v(location, country, machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO src_id FROM mhr_records
    WHERE process_group = $str$PCB$str$ AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF src_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = r.location AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records src WHERE src.id = $1', cols, sel)
      USING src_id, r.direct, r.indirect, r.labor, r.location, r.country, r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE '% twins inserted: %', $str$PCB$str$, n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE '% twins with no USA row (not inserted): %', $str$PCB$str$, missing;
  END IF;
END $pcba_india$;

INSERT INTO machining_reference_data (category, source_region, source_version, key, value, unit_type, notes, raw) VALUES
  ($str$lookup_table$str$, 'USA', $str$2026-PCB$str$, $str$assembly_rates$str$, $str$49$str$, NULL, $str$Staged from memory/PCBA/Assembly/assembly_rates.csv (researched, sourced: user decision 2026-11-23)$str$, $jsonb${"table_name":"assembly_rates","source_files":["PCBA/Assembly/assembly_rates.csv"],"status":"COMPLETE","columns":["item_key","operation","method","value_min","value_max","unit","conditions","source_url","source_date","source_note"],"rows":[{"item_key":"tht_insertion_parts_per_hr","operation":"manual_insertion","method":"unspecified_tht","value_min":200,"value_max":400,"unit":"components_per_hr","conditions":"best-expected manual insertion rate of through-hole components; no lead-type split","source_url":"https://www.pcbway.com/blog/Engineering_Technical/Component_Placement_onto_the_Printed_Circuit_Board.html","source_date":"2013-11-21","source_note":"PCBWay engineering blog. Stated range, not a measurement; equals about 9-18 s per component (not converted in cells)."},{"item_key":"tht_insertion_parts_per_hr","operation":"manual_insertion","method":"unspecified_tht","value_min":240,"value_max":240,"unit":"components_per_hr","conditions":"hand insertion rate including lead preparation time; input to an auto-insertion ROI model at US$15/hr labour","source_url":"https://www.slideshare.net/slideshow/auto-insertion-machine-roi-evaluation/53517298","source_date":"2026-11-23","source_note":"smthelp.com ROI evaluation deck (uploaded by an insertion-machine distributor; image filenames suggest 2015). Model input assumption, not a measurement."},{"item_key":null,"operation":"manual_insertion","method":"unspecified","value_min":50,"value_max":100,"unit":"components_per_hr","conditions":"skilled technician manual assembly; source does not say THT vs SMT or whether soldering is included","source_url":"https://www.allpcb.com/ar-SA/blog/pcb-assembly/manual-assembly-vs-automated-assembly-which-is-right-for-your-pcb.html","source_date":"2025-08-25","source_note":"ALLPCB blog estimate (\"might assemble\"). Not measured; low specificity."},{"item_key":null,"operation":"selective_solder","method":"miniwave_single_nozzle","value_min":60,"value_max":600,"unit":"s_per_board","conditions":"single miniwave, drag or dip mode, joints approached successively; depends on number of joints","source_url":"https://www.electronics.org/system/files/technical_resource/E8%26S23_02.pdf","source_date":"2026-11-23","source_note":"Zoch & Ott (SEHO Systems), IPC APEX paper: typical cycle times between 1 minute and 10 minutes per assembly (converted to seconds). Vendor typical range."},{"item_key":null,"operation":"selective_solder","method":"dip_multi_nozzle","value_min":20,"value_max":30,"unit":"s_per_board","conditions":"multi-nozzle dip with product-specific nozzle tool, all joints soldered simultaneously","source_url":"https://www.electronics.org/system/files/technical_resource/E8%26S23_02.pdf","source_date":"2026-11-23","source_note":"Zoch & Ott (SEHO Systems), IPC APEX paper: short cycle time ranging between 20 and 30 seconds. Vendor typical range."},{"item_key":"selective_solder_s_per_joint","operation":"selective_solder","method":"point","value_min":1.5,"value_max":3.5,"unit":"s_per_joint","conditions":"contact dwell time per joint after process optimisation, SAC305 pot 260-280 C; excludes travel/fluxing/preheat","source_url":"https://jlcpcb.com/blog/selective-soldering","source_date":"2026-02-05","source_note":"JLCPCB blog (published 2025-12-31, updated 2026-02-05). Dwell only; <1 s risks <75% barrel fill, >4 s risks copper dissolution."},{"item_key":null,"operation":"selective_solder","method":"unspecified","value_min":72,"value_max":72,"unit":"s_per_board","conditions":"worked example: industrial PLC board with 35 THT joints (terminal blocks, connectors, relay), programmed unattended run","source_url":"https://www.pcbcart.com/article/content/selective-soldering-roi-tht-cost.html","source_date":"2026-07-24","source_note":"PCBCart article: \"Assume 1.2 minutes/board cycle time\" (converted to 72 s). Illustrative assumption, not measured."},{"item_key":"wave_conveyor_m_per_min","operation":"wave_solder","method":"conveyor","value_min":2.5,"value_max":2.5,"unit":"m_per_min","conditions":"Ersa POWERFLOW, max working width 508 mm, finger conveyor","source_url":"https://kurtzersa.com/products/electronics-production/soldering-machines/wave-soldering-systems/powerflow","source_date":"2026-11-23","source_note":"Manufacturer page: Max. transport speed 2.5 m/min. Datasheet maximum, not a process setting."},{"item_key":"wave_conveyor_m_per_min","operation":"wave_solder","method":"conveyor","value_min":0.5,"value_max":2.5,"unit":"m_per_min","conditions":"Ersa POWERFLOW FIVE, finger transport, standard boards","source_url":"https://kurtzersa.com/products/electronics-production/soldering-machines/wave-soldering-systems/powerflow-five","source_date":"2026-11-23","source_note":"Manufacturer page: transport speed 0.5 to 2.5 m/min. Machine range."},{"item_key":null,"operation":"wave_solder","method":"conveyor_heavy_duty","value_min":0.5,"value_max":1.6,"unit":"m_per_min","conditions":"Ersa POWERFLOW FIVE heavy duty transport, boards up to 25 kg","source_url":"https://kurtzersa.com/products/electronics-production/soldering-machines/wave-soldering-systems/powerflow-five","source_date":"2026-11-23","source_note":"Manufacturer page: heavy duty 25 kg 0.5 to 1.6 m/min. Machine range."},{"item_key":"wave_conveyor_m_per_min","operation":"wave_solder","method":"conveyor","value_min":1,"value_max":1.8,"unit":"m_per_min","conditions":"practical transport speed setting; over 2 m/min has been used but is not standard; depends on board type and layout","source_url":"https://itweae.freshdesk.com/support/solutions/articles/42000072819-soldering-machine-capacity","source_date":"2020-04-22","source_note":"ITW EAE (Vitronics Soltec) support article \"Soldering machine capacity\". Manufacturer process guidance."},{"item_key":"wave_conveyor_m_pe