($str$PCB$str$, $str$Hand Solder$str$, $str$pcb_bench_operation$str$, 'not_modeled', NULL, NULL, 1144)
ON CONFLICT (process_group, process_name) DO UPDATE
SET machine_class = COALESCE(process_taxonomy.machine_class, EXCLUDED.machine_class),
    default_machine_name = COALESCE(process_taxonomy.default_machine_name, EXCLUDED.default_machine_name);

INSERT INTO process_calculator_mappings (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
SELECT v.grp, v.name, v.name, NULL, NULL, false, v.display_order, v.machine_class, pt.id
FROM process_taxonomy pt
JOIN (VALUES
($str$PCB$str$, $str$Stencil Print$str$, $str$pcba_stencil_printer$str$, 1133),
($str$PCB$str$, $str$Solder Paste Inspection$str$, $str$pcba_solder_paste_inspection$str$, 1134),
($str$PCB$str$, $str$Pick and Place$str$, $str$pcba_pick_and_place$str$, 1135),
($str$PCB$str$, $str$Reflow Solder$str$, $str$pcba_reflow$str$, 1136),
($str$PCB$str$, $str$Assembly AOI$str$, $str$pcba_aoi$str$, 1137),
($str$PCB$str$, $str$Wave Solder$str$, $str$pcba_wave_solder$str$, 1138),
($str$PCB$str$, $str$Selective Solder$str$, $str$pcba_selective_solder$str$, 1139),
($str$PCB$str$, $str$In-Circuit Test$str$, $str$pcba_in_circuit_test$str$, 1140),
($str$PCB$str$, $str$Assembly Flying Probe$str$, $str$pcba_flying_probe$str$, 1141),
($str$PCB$str$, $str$Depanel Router$str$, $str$pcba_depanel_router$str$, 1142),
($str$PCB$str$, $str$THT Insertion$str$, $str$pcb_bench_operation$str$, 1143),
($str$PCB$str$, $str$Hand Solder$str$, $str$pcb_bench_operation$str$, 1144)
) AS v(grp, name, machine_class, display_order)
  ON pt.process_group = v.grp AND pt.process_name = v.name
WHERE NOT EXISTS (SELECT 1 FROM process_calculator_mappings m WHERE m.process_group = v.grp AND m.operation = v.name)
ON CONFLICT (process_group, process_route, operation) DO NOTHING;

DO $pcba_check$
DECLARE usa integer; india integer; catalog integer;
BEGIN
  SELECT count(*) FILTER (WHERE location = 'USA'), count(*) FILTER (WHERE location = 'India') INTO usa, india
  FROM mhr_records WHERE process_group = 'PCB' AND machine_class LIKE 'pcba_%';
  SELECT count(*) INTO catalog FROM process_calculator_mappings WHERE process_group = 'PCB' AND operation IN ($str$Stencil Print$str$, $str$Solder Paste Inspection$str$, $str$Pick and Place$str$, $str$Reflow Solder$str$, $str$Assembly AOI$str$, $str$Wave Solder$str$, $str$Selective Solder$str$, $str$In-Circuit Test$str$, $str$Assembly Flying Probe$str$, $str$Depanel Router$str$, $str$THT Insertion$str$, $str$Hand Solder$str$);
  IF usa < 24 OR india < 24 OR catalog < 12 THEN
    RAISE EXCEPTION 'PCB assembly: % USA and % India machines (expected 24 each), % catalog rows (expected 12)', usa, india, catalog;
  END IF;
END $pcba_check$;

NOTIFY pgrst, 'reload schema';
